{
  "name": "SplatRotate - 3D Gaussian Splat Manipulator",
  "description": "An advanced 3D viewer for Gaussian Splats that allows precise rotation control along X, Y, and Z axes with export capabilities."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface RotationState {
  x: number;
  y: number;
  z: number;
}

export interface SplatConfig {
  url: string;
  name: string;
  rotation: RotationState;
  scale: number;
}

import React, { useState, useCallback, useRef } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Splat, Stage, PerspectiveCamera, Environment, Grid } from '@react-three/drei';
import { Download, Upload, RotateCcw, Share2, Info, Maximize, Settings2 } from 'lucide-react';
import ControlPanel from './components/ControlPanel';
import Header from './components/Header';
import { RotationState, SplatConfig } from './types';

// Default splat URL (A sample)
const DEFAULT_SPLAT = "https://huggingface.co/datasets/dylanebert/3dgs/resolve/main/kitchen/kitchen-7k.splat";

const App: React.FC = () => {
  const [rotation, setRotation] = useState<RotationState>({ x: 0, y: 0, z: 0 });
  const [splatUrl, setSplatUrl] = useState<string>(DEFAULT_SPLAT);
  const [splatName, setSplatName] = useState<string>("Sample Kitchen");
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const handleRotationChange = (axis: keyof RotationState, value: number) => {
    setRotation(prev => ({ ...prev, [axis]: value }));
  };

  const handleReset = () => {
    setRotation({ x: 0, y: 0, z: 0 });
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setSplatUrl(url);
      setSplatName(file.name);
    }
  };

  const handleExport = () => {
    // Export configuration as JSON
    const config: SplatConfig = {
      url: splatUrl,
      name: splatName,
      rotation,
      scale: 1,
    };
    const blob = new Blob([JSON.stringify(config, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `splat-config-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleCapture = () => {
    const canvas = document.querySelector('canvas');
    if (canvas) {
      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = `splat-capture-${Date.now()}.png`;
      link.click();
    }
  };

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-slate-950">
      {/* Header (Top Navigation) */}
      <Header />

      {/* Main Content Area */}
      <main className="relative flex-1 flex flex-col md:flex-row h-full pt-16">

        {/* Canvas Area */}
        <div className="flex-1 relative bg-slate-900 group">
          <Canvas
            shadows
            gl={{ preserveDrawingBuffer: true }}
            className="w-full h-full cursor-grab active:cursor-grabbing"
          >
            <PerspectiveCamera makeDefault position={[0, 2, 5]} />
            <OrbitControls makeDefault />

            <Stage environment="city" intensity={0.5}>
               <group 
                rotation={[
                  (rotation.x * Math.PI) / 180,
                  (rotation.y * Math.PI) / 180,
                  (rotation.z * Math.PI) / 180
                ]}
              >
                <Splat 
                  src={splatUrl} 
                />
              </group>
            </Stage>

            <Grid 
              infiniteGrid 
              fadeDistance={50} 
              sectionColor="#334155" 
              cellColor="#1e293b" 
              cellSize={1} 
              sectionSize={5} 
            />
            <Environment preset="city" />
          </Canvas>

          {/* Quick Actions Overlay */}
          <div className="absolute bottom-6 left-6 flex space-x-2 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity">
            <button 
              onClick={handleCapture}
              className="pointer-events-auto p-3 bg-slate-800/80 hover:bg-indigo-600 rounded-full text-white backdrop-blur-sm transition-all shadow-lg"
              title="Capture Screenshot"
            >
              <Maximize className="w-5 h-5" />
            </button>
            <button 
              onClick={handleReset}
              className="pointer-events-auto p-3 bg-slate-800/80 hover:bg-indigo-600 rounded-full text-white backdrop-blur-sm transition-all shadow-lg"
              title="Reset View"
            >
              <RotateCcw className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Control Sidebar */}
        <aside className={`${isSidebarOpen ? 'w-full md:w-80' : 'w-0 overflow-hidden'} transition-all duration-300 bg-slate-900 border-l border-slate-800 flex flex-col shadow-2xl z-10`}>
          <div className="p-6 flex flex-col h-full overflow-y-auto custom-scrollbar">
            <div className="flex items-center justify-between mb-8">
              <h2 className="text-lg font-semibold flex items-center gap-2">
                <Settings2 className="w-5 h-5 text-indigo-400" />
                Splat Controls
              </h2>
            </div>

            <ControlPanel 
              rotation={rotation} 
              onRotationChange={handleRotationChange}
              onReset={handleReset}
              splatName={splatName}
            />

            <div className="mt-auto pt-8 border-t border-slate-800 space-y-4">
              <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-slate-700 border-dashed rounded-xl cursor-pointer bg-slate-800/30 hover:bg-slate-800/50 transition-colors">
                <div className="flex flex-col items-center justify-center pt-5 pb-6">
                  <Upload className="w-8 h-8 text-slate-400 mb-2" />
                  <p className="text-xs text-slate-400 font-medium">Click to upload .splat / .ply</p>
                </div>
                <input type="file" className="hidden" accept=".splat,.ply" onChange={handleFileUpload} />
              </label>

              <button 
                onClick={handleExport}
                className="w-full flex items-center justify-center gap-2 py-3 px-4 bg-indigo-600 hover:bg-indigo-500 rounded-xl text-white font-medium transition-colors shadow-lg shadow-indigo-900/20"
              >
                <Download className="w-4 h-4" />
                Export Config
              </button>

              <p className="text-[10px] text-center text-slate-500 italic">
                SplatRotate v1.0 • Built with Three.js
              </p>
            </div>
          </div>
        </aside>

        {/* Sidebar Toggle (Mobile) */}
        <button 
          onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          className="md:hidden absolute top-4 right-4 z-20 p-2 bg-indigo-600 rounded-lg"
        >
          <Settings2 className="w-6 h-6" />
        </button>
      </main>
    </div>
  );
};

export default App;

