export default ControlPanel;

import React, { useState, useRef } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Splat, Stage, PerspectiveCamera, Environment, Grid } from '@react-three/drei';
import { Download, Upload, RotateCcw, Maximize, Settings2, Box, FileCode } from 'lucide-react';
import ControlPanel from './components/ControlPanel';
import Header from './components/Header';
import { RotationState, SplatConfig } from './types';

const App: React.FC = () => {
  const [rotation, setRotation] = useState<RotationState>({ x: 0, y: 0, z: 0 });
  const [splatUrl, setSplatUrl] = useState<string | null>(null);
  const [splatName, setSplatName] = useState<string>("");
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const handleRotationChange = (axis: keyof RotationState, value: number) => {
    setRotation(prev => ({ ...prev, [axis]: value }));
  };

  const handleReset = () => {
    setRotation({ x: 0, y: 0, z: 0 });
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      // Clean up previous URL if it exists
      if (splatUrl) URL.revokeObjectURL(splatUrl);

      const url = URL.createObjectURL(file);
      setSplatUrl(url);
      setSplatName(file.name);
      handleReset(); // Reset rotation on new file upload
    }
  };

  const handleExport = () => {
    if (!splatUrl) return;

    const config: SplatConfig = {
      url: splatUrl,
      name: splatName,
      rotation,
      scale: 1,
    };
    const blob = new Blob([JSON.stringify(config, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${splatName.split('.')[0]}-config.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleCapture = () => {
    const canvas = document.querySelector('canvas');
    if (canvas) {
      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = `splat-capture-${Date.now()}.png`;
      link.click();
    }
  };

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-slate-950">
      <Header />

      <main className="relative flex-1 flex flex-col md:flex-row h-full pt-16">

        {/* Canvas Area / Empty State */}
        <div className="flex-1 relative bg-slate-900 group">
          {splatUrl ? (
            <>
              <Canvas
                shadows
                gl={{ preserveDrawingBuffer: true }}
                className="w-full h-full cursor-grab active:cursor-grabbing"
              >
                <PerspectiveCamera makeDefault position={[0, 2, 5]} />
                <OrbitControls makeDefault />

                <Stage environment="city" intensity={0.5}>
                   <group 
                    rotation={[
                      (rotation.x * Math.PI) / 180,
                      (rotation.y * Math.PI) / 180,
                      (rotation.z * Math.PI) / 180
                    ]}
                  >
                    <Splat src={splatUrl} />
                  </group>
                </Stage>

                <Grid 
                  infiniteGrid 
                  fadeDistance={50} 
                  sectionColor="#334155" 
                  cellColor="#1e293b" 
                  cellSize={1} 
                  sectionSize={5} 
                />
                <Environment preset="city" />
              </Canvas>

              <div className="absolute bottom-6 left-6 flex space-x-2 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                  onClick={handleCapture}
                  className="pointer-events-auto p-3 bg-slate-800/80 hover:bg-indigo-600 rounded-full text-white backdrop-blur-sm transition-all shadow-lg"
                  title="Capture Screenshot"
                >
                  <Maximize className="w-5 h-5" />
                </button>
                <button 
                  onClick={handleReset}
                  className="pointer-events-auto p-3 bg-slate-800/80 hover:bg-indigo-600 rounded-full text-white backdrop-blur-sm transition-all shadow-lg"
                  title="Reset Orientation"
                >
                  <RotateCcw className="w-5 h-5" />
                </button>
              </div>
            </>
          ) : (
            <div className="w-full h-full flex flex-col items-center justify-center p-8 text-center">
              <div className="w-24 h-24 mb-6 bg-indigo-500/10 rounded-3xl flex items-center justify-center border border-indigo-500/20 shadow-2xl shadow-indigo-500/5 animate-pulse">
                <Box className="w-12 h-12 text-indigo-500" />
              </div>
              <h2 className="text-2xl font-bold text-white mb-2">No Splat Loaded</h2>
              <p className="text-slate-400 max-w-md mb-8">
                Upload a 3D Gaussian Splat (.ply or .splat) to begin rotating and configuring your visualization.
              </p>
              <label className="flex items-center gap-3 py-4 px-8 bg-indigo-600 hover:bg-indigo-500 rounded-2xl text-white font-semibold transition-all shadow-xl shadow-indigo-600/20 cursor-pointer">
                <Upload className="w-5 h-5" />
                Choose PLY or SPLAT File
                <input type="file" className="hidden" accept=".splat,.ply" onChange={handleFileUpload} />
              </label>
            </div>
          )}
        </div>

        {/* Control Sidebar */}
        <aside className={`${isSidebarOpen ? 'w-full md:w-80' : 'w-0 overflow-hidden'} transition-all duration-300 bg-slate-900 border-l border-slate-800 flex flex-col shadow-2xl z-10`}>
          <div className="p-6 flex flex-col h-full overflow-y-auto custom-scrollbar">
            <div className="flex items-center justify-between mb-8">
              <h2 className="text-lg font-semibold flex items-center gap-2 text-slate-100">
                <Settings2 className="w-5 h-5 text-indigo-400" />
                Splat Controls
              </h2>
            </div>

            {splatUrl ? (
              <ControlPanel 
                rotation={rotation} 
                onRotationChange={handleRotationChange}
                onReset={handleReset}
                splatName={splatName}
              />
            ) : (
              <div className="flex flex-col items-center justify-center py-12 px-4 bg-slate-800/20 rounded-2xl border border-slate-800 border-dashed">
                <FileCode className="w-8 h-8 text-slate-600 mb-3" />
                <p className="text-sm text-slate-500 text-center">Controls will appear after you upload a file.</p>
              </div>
            )}

            <div className="mt-auto pt-8 border-t border-slate-800 space-y-4">
              <label className="flex flex-col items-center justify-center w-full h-24 border-2 border-slate-700 border-dashed rounded-xl cursor-pointer bg-slate-800/30 hover:bg-slate-800/50 transition-colors">
                <div className="flex flex-col items-center justify-center pt-2">
                  <Upload className="w-5 h-5 text-slate-400 mb-2" />
                  <p className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">Change Input File</p>
                </div>
                <input type="file" className="hidden" accept=".splat,.ply" onChange={handleFileUpload} />
              </label>

              <button 
                onClick={handleExport}
                disabled={!splatUrl}
                className={`w-full flex items-center justify-center gap-2 py-3 px-4 rounded-xl font-medium transition-all shadow-lg ${
                  splatUrl 
                    ? 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-indigo-900/20' 
                    : 'bg-slate-800 text-slate-500 cursor-not-allowed opacity-50'
                }`}
              >
                <Download className="w-4 h-4" />
                Export Config
              </button>

              <p className="text-[10px] text-center text-slate-500 italic">
                SplatRotate v1.0 • Built with Three.js
              </p>
            </div>
          </div>
        </aside>

        {/* Sidebar Toggle (Mobile) */}
        <button 
          onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          className="md:hidden absolute top-4 right-4 z-20 p-2 bg-indigo-600 rounded-lg text-white shadow-lg"
        >
          <Settings2 className="w-6 h-6" />
        </button>
      </main>
    </div>
  );
};

export default App;

export interface Vector3 {
  x: number;
  y: number;
  z: number;
}

export interface SplatTransform {
  position: Vector3;
  rotation: Vector3;
  scale: number;
}

export interface SplatConfig extends SplatTransform {
  url: string;
  name: string;
}

import React, { useState, useCallback } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Splat, Stage, PerspectiveCamera, Environment, Grid } from '@react-three/drei';
import { Download, Upload, RotateCcw, Maximize, Settings2, Box, FileCode, Move, Layers } from 'lucide-react';
import ControlPanel from './components/ControlPanel';
import Header from './components/Header';
import { SplatTransform, Vector3 } from './types';

const App: React.FC = () => {
  const [transform, setTransform] = useState<SplatTransform>({
    position: { x: 0, y: 0, z: 0 },
    rotation: { x: 0, y: 0, z: 0 },
    scale: 1,
  });

  const [splatUrl, setSplatUrl] = useState<string | null>(null);
  const [splatName, setSplatName] = useState<string>("");
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const handleTransformChange = useCallback((category: keyof SplatTransform, axis: keyof Vector3 | 'all', value: number) => {
    setTransform(prev => {
      if (category === 'scale') {
        return { ...prev, scale: value };
      }
      return {
        ...prev,
        [category]: {
          ...(prev[category] as Vector3),
          [axis as keyof Vector3]: value
        }
      };
    });
  }, []);

  const handleReset = () => {
    setTransform({
      position: { x: 0, y: 0, z: 0 },
      rotation: { x: 0, y: 0, z: 0 },
      scale: 1,
    });
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (splatUrl) URL.revokeObjectURL(splatUrl);
      const url = URL.createObjectURL(file);
      setSplatUrl(url);
      setSplatName(file.name);
      handleReset();
    }
  };

  const handleExport = () => {
    if (!splatUrl) return;
    const exportData = {
      name: splatName,
      timestamp: new Date().toISOString(),
      ...transform
    };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${splatName.split('.')[0]}-transform.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleCapture = () => {
    const canvas = document.querySelector('canvas');
    if (canvas) {
      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = `supersplat-${Date.now()}.png`;
      link.click();
    }
  };

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-slate-950">
      <Header />

      <main className="relative flex-1 flex flex-col md:flex-row h-full pt-16">
        {/* Viewport */}
        <div className="flex-1 relative bg-[#0a0a0c] group">
          {splatUrl ? (
            <>
              <Canvas
                shadows
                gl={{ preserveDrawingBuffer: true, antialias: true }}
                className="w-full h-full cursor-grab active:cursor-grabbing"
              >
                <PerspectiveCamera makeDefault position={[0, 2, 5]} />
                <OrbitControls makeDefault />

                <Stage environment="city" intensity={0.5} contactShadow={false}>
                   <group 
                    position={[transform.position.x, transform.position.y, transform.position.z]}
                    rotation={[
                      (transform.rotation.x * Math.PI) / 180,
                      (transform.rotation.y * Math.PI) / 180,
                      (transform.rotation.z * Math.PI) / 180
                    ]}
                    scale={[transform.scale, transform.scale, transform.scale]}
                  >
                    <Splat src={splatUrl} />
                  </group>
                </Stage>

                <Grid 
                  infiniteGrid 
                  fadeDistance={30} 
                  sectionColor="#1e293b" 
                  cellColor="#0f172a" 
                  cellSize={0.5} 
                  sectionSize={2.5} 
                />
                <Environment preset="city" />
              </Canvas>

              <div className="absolute top-4 left-4 flex gap-2 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity">
                 <div className="bg-slate-900/90 backdrop-blur text-[10px] text-indigo-400 font-mono px-3 py-1.5 rounded-full border border-slate-700">
                    SPLAT RENDERER ACTIVE
                 </div>
              </div>

              <div className="absolute bottom-6 right-6 flex space-x-2 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                  onClick={handleCapture}
