import React, { useEffect, useRef } from 'react';
import * as pc from 'playcanvas';
import { SplatTransform } from '../types';

interface PlayCanvasViewerProps {
  url: string;
  transform: SplatTransform;
}

const PlayCanvasViewer: React.FC<PlayCanvasViewerProps> = ({ url, transform }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const appRef = useRef<pc.Application | null>(null);
  const splatEntityRef = useRef<pc.Entity | null>(null);

  useEffect(() => {
    if (!canvasRef.current || !containerRef.current) return;

    // Initialize PlayCanvas Application
    const app = new pc.Application(canvasRef.current, {
      mouse: new pc.Mouse(canvasRef.current),
      touch: new pc.TouchDevice(canvasRef.current),
      graphicsDeviceOptions: { antialias: true, alpha: false }
    });

    app.setCanvasFillMode(pc.FILLMODE_FILL_WINDOW);
    app.setCanvasResolution(pc.RESOLUTION_AUTO);
    app.start();
    appRef.current = app;

    // Camera Setup
    const camera = new pc.Entity('Camera');
    camera.addComponent('camera', {
      clearColor: new pc.Color(0.04, 0.04, 0.05)
    });
    camera.setPosition(0, 1, 5);
    app.root.addChild(camera);

    // Basic Orbit Control Logic (simplified)
    let isDragging = false;
    let lastX = 0;
    let lastY = 0;
    let yaw = 0;
    let pitch = 0;
    let distance = 5;

    const handleMouseDown = (e: MouseEvent) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    };

    const handleMouseMove = (e: MouseEvent) => {
      if (!isDragging) return;
      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;
      yaw -= dx * 0.5;
      pitch -= dy * 0.5;
      pitch = Math.max(-89, Math.min(89, pitch));
      lastX = e.clientX;
      lastY = e.clientY;
    };

    const handleMouseUp = () => { isDragging = false; };
    const handleWheel = (e: WheelEvent) => {
      distance += e.deltaY * 0.01;
      distance = Math.max(0.5, Math.min(50, distance));
    };

    canvasRef.current.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    canvasRef.current.addEventListener('wheel', handleWheel);

    app.on('update', (dt) => {
      const rot = new pc.Quat().setFromEulerAngles(pitch, yaw, 0);
      const pos = rot.transformVector(new pc.Vec3(0, 0, distance));
      camera.setRotation(rot);
      camera.setPosition(pos);
    });

    // Splat Entity
    const splatEntity = new pc.Entity('GSplat');
    app.root.addChild(splatEntity);
    splatEntityRef.current = splatEntity;

    // Load GSplat Asset
    const asset = new pc.Asset('splat', 'gsplat', { url: url });
    app.assets.add(asset);
    app.assets.load(asset);

    asset.ready(() => {
      splatEntity.addComponent('gsplat', {
        asset: asset
      });
    });

    // Cleanup
    return () => {
      canvasRef.current?.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      canvasRef.current?.removeEventListener('wheel', handleWheel);
      app.destroy();
    };
  }, [url]);

  // Update Transform in PlayCanvas when React state changes
  useEffect(() => {
    const entity = splatEntityRef.current;
    if (!entity) return;

    entity.setPosition(transform.position.x, transform.position.y, transform.position.z);
    entity.setEulerAngles(transform.rotation.x, transform.rotation.y, transform.rotation.z);
    entity.setLocalScale(transform.scale, transform.scale, transform.scale);
  }, [transform]);

  return (
    <div ref={containerRef} className="w-full h-full relative overflow-hidden">
      <canvas ref={canvasRef} />
    </div>
  );
};

export default PlayCanvasViewer;

import React, { useState, useCallback } from 'react';
import { Download, Upload, RotateCcw, Maximize, Settings2, Box, Move, Layers, Zap } from 'lucide-react';
import ControlPanel from './components/ControlPanel';
import Header from './components/Header';
import PlayCanvasViewer from './components/PlayCanvasViewer';
import { SplatTransform, Vector3 } from './types';

const App: React.FC = () => {
  const [transform, setTransform] = useState<SplatTransform>({
    position: { x: 0, y: 0, z: 0 },
    rotation: { x: 0, y: 0, z: 0 },
    scale: 1,
  });

  const [splatUrl, setSplatUrl] = useState<string | null>(null);
  const [splatName, setSplatName] = useState<string>("");
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const handleTransformChange = useCallback((category: keyof SplatTransform, axis: keyof Vector3 | 'all', value: number) => {
    setTransform(prev => {
      if (category === 'scale') {
        return { ...prev, scale: value };
      }
      return {
        ...prev,
        [category]: {
          ...(prev[category] as Vector3),
          [axis as keyof Vector3]: value
        }
      };
    });
  }, []);

  const handleReset = () => {
    setTransform({
      position: { x: 0, y: 0, z: 0 },
      rotation: { x: 0, y: 0, z: 0 },
      scale: 1,
    });
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (splatUrl) URL.revokeObjectURL(splatUrl);
      const url = URL.createObjectURL(file);
      setSplatUrl(url);
      setSplatName(file.name);
      handleReset();
    }
  };

  const handleExport = () => {
    if (!splatUrl) return;
    const exportData = {
      name: splatName,
      engine: "PlayCanvas",
      timestamp: new Date().toISOString(),
      ...transform
    };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${splatName.split('.')[0]}-supersplat-config.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleCapture = () => {
    const canvas = document.querySelector('canvas');
    if (canvas) {
      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = `supersplat-pc-${Date.now()}.png`;
      link.click();
    }
  };

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#08090a]">
      <Header />

      <main className="relative flex-1 flex flex-col md:flex-row h-full pt-16">
        {/* PlayCanvas Viewport */}
        <div className="flex-1 relative group overflow-hidden">
          {splatUrl ? (
            <>
              <PlayCanvasViewer url={splatUrl} transform={transform} />

              <div className="absolute top-4 left-4 flex gap-2 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                 <div className="bg-slate-900/90 backdrop-blur text-[10px] text-indigo-400 font-bold px-3 py-1.5 rounded-md border border-slate-800 flex items-center gap-2 shadow-2xl">
                    <Zap className="w-3 h-3 fill-indigo-400" />
                    PLAYCANVAS ENGINE ACTIVE
                 </div>
              </div>

              <div className="absolute bottom-6 right-6 flex space-x-2 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                <button 
                  onClick={handleCapture}
                  className="pointer-events-auto p-3 bg-slate-800/80 hover:bg-indigo-600 rounded-lg text-white backdrop-blur-sm transition-all shadow-2xl border border-slate-700/50"
                  title="Capture Frame"
                >
                  <Maximize className="w-5 h-5" />
                </button>
                <button 
                  onClick={handleReset}
                  className="pointer-events-auto p-3 bg-slate-800/80 hover:bg-indigo-600 rounded-lg text-white backdrop-blur-sm transition-all shadow-2xl border border-slate-700/50"
                  title="Reset Entity"
                >
                  <RotateCcw className="w-5 h-5" />
                </button>
              </div>
            </>
          ) : (
            <div className="w-full h-full flex flex-col items-center justify-center p-8 text-center bg-[#08090a]">
              <div className="w-24 h-24 mb-6 relative">
                 <div className="absolute inset-0 bg-indigo-500 rounded-3xl blur-3xl opacity-10 animate-pulse"></div>
                 <div className="relative w-24 h-24 bg-slate-900 rounded-3xl flex items-center justify-center border border-slate-800 shadow-2xl">
                    <Box className="w-12 h-12 text-slate-700" />
                 </div>
              </div>
              <h2 className="text-3xl font-black text-white mb-2 tracking-tight uppercase">SuperSplat</h2>
              <p className="text-slate-500 max-w-sm mb-10 text-sm leading-relaxed font-medium">
                Professional PlayCanvas-powered toolkit for high-fidelity Gaussian Splat manipulation.
              </p>
              <label className="group relative flex items-center gap-4 py-5 px-12 bg-indigo-600 hover:bg-indigo-500 rounded-lg text-white font-black transition-all shadow-2xl shadow-indigo-600/20 cursor-pointer overflow-hidden uppercase tracking-widest text-xs">
                <Upload className="w-5 h-5 relative z-10" />
                <span className="relative z-10">Import Dataset</span>
                <input type="file" className="hidden" accept=".splat,.ply" onChange={handleFileUpload} />
              </label>
              <p className="mt-8 text-[10px] text-slate-700 font-bold tracking-widest uppercase">Supports .ply (Splat Format) & .splat</p>
            </div>
          )}
        </div>

        {/* PlayCanvas Inspector Sidebar */}
        <aside className={`${isSidebarOpen ? 'w-full md:w-80' : 'w-0 overflow-hidden'} transition-all duration-300 bg-[#0c0d10] border-l border-white/[0.03] flex flex-col z-10 shadow-[-20px_0_50px_rgba(0,0,0,0.5)]`}>
