              <h2 className="text-xs font-black uppercase tracking-[0.2em] text-slate-400">Inspector</h2>
            </div>

            {splatUrl ? (
              <ControlPanel 
                transform={transform} 
                onTransformChange={handleTransformChange}
                onReset={handleReset}
                splatName={splatName}
              />
            ) : (
              <div className="flex flex-col items-center justify-center py-20 px-4 bg-white/[0.01] rounded-lg border border-white/[0.03] border-dashed">
                <Layers className="w-10 h-10 text-slate-800 mb-4" />
