                  <Move className="w-4 h-4 text-slate-700 group-hover:text-indigo-500 transition-colors" />
                  <p className="text-[10px] text-slate-600 font-black uppercase tracking-[0.2em] group-hover:text-slate-300 transition-colors">Swap Model</p>
                </div>
                <input type="file" className="hidden" accept=".splat,.ply" onChange={handleFileUpload} />
              </label>

              <button 
