  // Helper: Quaternion math for rotation baking
  const applyTransform = (buffer: ArrayBuffer, tx: SplatTransform): ArrayBuffer => {
    const view = new DataView(buffer);
    const newBuffer = buffer.slice(0);
    const newView = new DataView(newBuffer);
    const splatSize = 32; // Standard .splat format chunk size
    const count = buffer.byteLength / splatSize;

    // Convert Euler degrees to Radians
    const rx = tx.rotation.x * (Math.PI / 180);
    const ry = tx.rotation.y * (Math.PI / 180);
    const rz = tx.rotation.z * (Math.PI / 180);

    // Rotation Matrices
    const cosX = Math.cos(rx), sinX = Math.sin(rx);
    const cosY = Math.cos(ry), sinY = Math.sin(ry);
    const cosZ = Math.cos(rz), sinZ = Math.sin(rz);

    for (let i = 0; i < count; i++) {
      const offset = i * splatSize;

      // 1. Position Bake (0-12 bytes: float x, y, z)
      let px = view.getFloat32(offset + 0, true);
      let py = view.getFloat32(offset + 4, true);
      let pz = view.getFloat32(offset + 8, true);

      // Apply Scale
      px *= tx.scale;
      py *= tx.scale;
      pz *= tx.scale;

      // Apply Rotation (XYZ Order)
      // Rotate X
      let ty = py * cosX - pz * sinX;
      let tz = py * sinX + pz * cosX;
      py = ty; pz = tz;
      // Rotate Y
      let tx_ = px * cosY + pz * sinY;
      tz = -px * sinY + pz * cosY;
      px = tx_; pz = tz;
      // Rotate Z
      tx_ = px * cosZ - py * sinZ;
      ty = px * sinZ + py * cosZ;
      px = tx_; py = ty;

      // Apply Translation
      px += tx.position.x;
      py += tx.position.y;
      pz += tx.position.z;

      newView.setFloat32(offset + 0, px, true);
      newView.setFloat32(offset + 4, py, true);
      newView.setFloat32(offset + 8, pz, true);

      // 2. Scale Bake (12-24 bytes: float sx, sy, sz)
      if (tx.scale !== 1) {
        let sx = view.getFloat32(offset + 12, true);
        let sy = view.getFloat32(offset + 16, true);
        let sz = view.getFloat32(offset + 20, true);
        newView.setFloat32(offset + 12, sx * tx.scale, true);
        newView.setFloat32(offset + 16, sy * tx.scale, true);
        newView.setFloat32(offset + 20, sz * tx.scale, true);
      }

