        {/* Sidebar */}
        <aside className={`${isSidebarOpen ? 'w-full md:w-80' : 'w-0 overflow-hidden'} transition-all duration-500 bg-[#08090b] border-l border-white/[0.03] flex flex-col z-10 shadow-[-20px_0_100px_rgba(0,0,0,0.9)]`}>
